-- MOTOSEC 237 v0.1 — schéma de base (SQLite en développement, portable PostgreSQL).
-- Règles de portabilité PostgreSQL : types TEXT / INTEGER / REAL / BOOLEAN
-- (BOOLEAN = INTEGER 0/1 sous SQLite), clés UUID en TEXT, horodatages ISO 8601
-- en TEXT, jamais de type propre à un seul moteur. La bascule PostgreSQL est
-- documentée dans docs/BASE-DONNEES.md (SERIAL -> INTEGER GENERATED BY DEFAULT
-- AS IDENTITY, BOOLEAN natif, index spatiaux PostGIS en phase ultérieure).
-- Zone pilote : Meiganga, Mbéré, Adamaoua, Cameroun (6.5167, 14.3).
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS app_users (
    id TEXT PRIMARY KEY,
    phone TEXT NOT NULL UNIQUE,
    full_name TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'client' CHECK (role IN ('client','driver','admin','security')),
    language TEXT NOT NULL DEFAULT 'fr' CHECK (language IN ('fr','en')),
    emergency_contact_id TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS emergency_contacts (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    full_name TEXT NOT NULL,
    phone TEXT NOT NULL,
    relation TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS drivers (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL UNIQUE REFERENCES app_users(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','suspended','rejected')),
    id_document_type TEXT,
    id_document_ref TEXT,
    licence_number TEXT,
    verified_at TEXT,
    rating_avg REAL NOT NULL DEFAULT 0,
    online INTEGER NOT NULL DEFAULT 0,
    rejection_reason TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS motorcycles (
    id TEXT PRIMARY KEY,
    driver_id TEXT NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,
    plate TEXT NOT NULL UNIQUE,
    box_code TEXT UNIQUE,
    brand TEXT,
    model TEXT,
    color TEXT,
    owner_name TEXT,
    verified INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS rides (
    id TEXT PRIMARY KEY,
    op_id TEXT UNIQUE,
    client_id TEXT NOT NULL REFERENCES app_users(id),
    driver_id TEXT REFERENCES drivers(id),
    motorcycle_id TEXT REFERENCES motorcycles(id),
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','requested','assigned','ongoing','completed','cancelled')),
    origin_lat REAL NOT NULL,
    origin_lng REAL NOT NULL,
    origin_label TEXT,
    dest_lat REAL NOT NULL,
    dest_lng REAL NOT NULL,
    dest_label TEXT,
    distance_km REAL,
    duration_min REAL,
    fare_fcfa INTEGER,
    otp_start TEXT,
    otp_attempts INTEGER NOT NULL DEFAULT 0,
    payment_method TEXT CHECK (payment_method IN ('cash','mtn_momo','orange_money')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS parcels (
    id TEXT PRIMARY KEY,
    op_id TEXT UNIQUE,
    ride_id TEXT REFERENCES rides(id),
    sender_id TEXT NOT NULL REFERENCES app_users(id),
    receiver_name TEXT NOT NULL,
    receiver_phone TEXT NOT NULL,
    description TEXT,
    declared_value_fcfa INTEGER,
    tracking_code TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL DEFAULT 'created' CHECK (status IN ('created','picked_up','in_transit','delivered','failed')),
    otp_delivery TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS gps_points (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ride_id TEXT NOT NULL REFERENCES rides(id) ON DELETE CASCADE,
    lat REAL NOT NULL CHECK (lat BETWEEN -90 AND 90),
    lng REAL NOT NULL CHECK (lng BETWEEN -180 AND 180),
    accuracy_m REAL,
    speed_kmh REAL,
    recorded_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_gps_ride_time ON gps_points (ride_id, recorded_at);

CREATE TABLE IF NOT EXISTS ride_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ride_id TEXT NOT NULL REFERENCES rides(id) ON DELETE CASCADE,
    op_id TEXT UNIQUE,
    event_type TEXT NOT NULL,
    detail TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_events_ride ON ride_events (ride_id, created_at);

CREATE TABLE IF NOT EXISTS incidents (
    id TEXT PRIMARY KEY,
    ride_id TEXT REFERENCES rides(id),
    reporter_id TEXT REFERENCES app_users(id),
    kind TEXT NOT NULL CHECK (kind IN ('sos','deviation','immobilisation','signal_loss','other')),
    status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','qualified','resolved','closed')),
    note TEXT,
    last_lat REAL,
    last_lng REAL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
-- IMPORTANT : une anomalie GPS n'est JAMAIS assimilee automatiquement a une
-- agression ou a un vol. Les alertes sont qualifiees par un operateur humain.

CREATE TABLE IF NOT EXISTS payment_transactions (
    id TEXT PRIMARY KEY,
    ride_id TEXT REFERENCES rides(id),
    method TEXT NOT NULL CHECK (method IN ('cash','mtn_momo','orange_money')),
    amount_fcfa INTEGER NOT NULL CHECK (amount_fcfa >= 0),
    commission_fcfa INTEGER NOT NULL DEFAULT 0,
    reference TEXT UNIQUE,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','success','failed','refunded')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS tracking_devices (
    id TEXT PRIMARY KEY,
    motorcycle_id TEXT REFERENCES motorcycles(id),
    device_code TEXT NOT NULL UNIQUE,
    active INTEGER NOT NULL DEFAULT 1,
    last_seen_at TEXT
);

CREATE TABLE IF NOT EXISTS notifications (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    read INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS ratings (
    id TEXT PRIMARY KEY,
    ride_id TEXT NOT NULL REFERENCES rides(id),
    rater_id TEXT NOT NULL REFERENCES app_users(id),
    driver_id TEXT REFERENCES drivers(id),
    stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5),
    comment TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS devices (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT NOT NULL,
    token TEXT UNIQUE NOT NULL,
    revoked INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS operations (
    op_id TEXT PRIMARY KEY,
    device_id TEXT NOT NULL,
    type TEXT NOT NULL,
    payload TEXT NOT NULL,
    payload_hash TEXT NOT NULL,
    status TEXT NOT NULL,
    received_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS otp_codes (
    phone TEXT PRIMARY KEY,
    code_hash TEXT NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS audit (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    actor TEXT NOT NULL,
    action TEXT NOT NULL,
    detail TEXT NOT NULL,
    at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_rides_client ON rides (client_id, created_at);
CREATE INDEX IF NOT EXISTS idx_rides_driver_status ON rides (driver_id, status);
CREATE INDEX IF NOT EXISTS idx_rides_status ON rides (status, created_at);
